package com.mealflex.growth.controller;
import com.mealflex.growth.service.SellerGrowthAnalyticsService; import com.mealflex.security.UserPrincipal; import lombok.RequiredArgsConstructor; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/v1/seller/stores/{storeId}/growth-analytics") @RequiredArgsConstructor public class SellerGrowthAnalyticsController {private final SellerGrowthAnalyticsService service;@GetMapping public ResponseEntity<Map<String,Object>> get(@AuthenticationPrincipal UserPrincipal p,@PathVariable Long storeId,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate startDate,@RequestParam @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate endDate){return ResponseEntity.ok(service.metrics(p.getId(),storeId,startDate,endDate));}}
